// Voice-over for the mentor stage.
//
// 1. Neural voice (preferred): POST /mentor_voice returns an MP3 generated by
//    edge-tts on the server (cached in tmp/cache/mentor_voices/). Clips are
//    prefetched and kept as blob URLs, so each line plays instantly after the first.
// 2. Browser voice (fallback): window.speechSynthesis with per-coach pitch/rate,
//    used only if the server answers 204 (edge-tts unavailable) or the request fails.
//
// Browsers only allow sound after the user has interacted with the page. Coming
// from Step 1 via a Turbo link click counts; a hard reload does not. In that case
// speak() reports `blocked` and the stage's Sound button pulses. One click on it
// unlocks sound for the rest of the visit.

// Voices differ per OS/browser, so each profile lists preferred voice names in
// order and falls back to any English voice. pitch/rate shape the character.
// (Only used for the browser fallback; neural voices are set in mentor_voice.rb.)
const FEMALE = ["Samantha", "Karen", "Moira", "Tessa", "Victoria", "Serena", "Google UK English Female", "Google US English", "Microsoft Aria", "Microsoft Jenny", "Microsoft Zira", "Female"]
const MALE = ["Daniel", "Alex", "Aaron", "Arthur", "Fred", "Google UK English Male", "Microsoft Guy", "Microsoft Ryan", "Microsoft David", "Male"]

export const VOICE_PROFILES = {
  goggins: { prefer: MALE, pitch: 0.75, rate: 1.05 },   // deep, intense, powerful
  arnold: { prefer: MALE, pitch: 0.65, rate: 0.85 },    // deep, heavy, commanding
  yoda: { prefer: MALE, pitch: 0.7, rate: 0.8 },        // slow, measured, low register
  sonic: { prefer: MALE, pitch: 1.35, rate: 1.25 },     // high-energy, fast, youthful
  mikasa: { prefer: FEMALE, pitch: 1.05, rate: 0.95 },  // calm, focused, steady (female voice if available)
  jonah: { prefer: MALE, pitch: 1.0, rate: 1.0 },       // casual, conversational
  default: { prefer: MALE, pitch: 1.0, rate: 1.0 }
}

class BrowserVoice {
  constructor(profile) {
    this.profile = profile
    this.synth = window.speechSynthesis
  }

  get supported() {
    return Boolean(this.synth && window.SpeechSynthesisUtterance)
  }

  pickVoice() {
    const voices = this.synth.getVoices().filter((v) => v.lang?.toLowerCase().startsWith("en"))
    for (const name of this.profile.prefer) {
      const match = voices.find((v) => v.name.includes(name))
      if (match) return match
    }
    return voices.find((v) => v.default) || voices[0] || null
  }

  // Resolves to "ended", "blocked" (needs a user gesture) or "failed".
  speak(text) {
    if (!this.supported) return Promise.resolve("failed")
    this.synth.cancel()
    return new Promise((done) => {
      // Some browsers drop a blocked utterance without any event; don't wait forever
      const fallback = setTimeout(() => done("ended"), 2500 + text.length * 90)
      const resolve = (result) => { clearTimeout(fallback); done(result) }
      const utterance = new SpeechSynthesisUtterance(text)
      const voice = this.pickVoice()
      if (voice) utterance.voice = voice
      utterance.lang = voice?.lang || "en-US"
      utterance.rate = this.profile.rate
      utterance.pitch = this.profile.pitch
      utterance.onend = () => resolve("ended")
      utterance.onerror = (event) => {
        // "interrupted"/"canceled" happen when we cancel on purpose
        if (event.error === "not-allowed") resolve("blocked")
        else if (event.error === "interrupted" || event.error === "canceled") resolve("ended")
        else resolve("failed")
      }
      this.synth.speak(utterance)
    })
  }

  cancel() {
    if (this.supported) this.synth.cancel()
  }
}

// Plays the server-generated neural MP3s through one shared <audio> element.
class NeuralVoice {
  constructor({ url, slug }) {
    this.url = url
    this.slug = slug
    this.clips = new Map() // text → Promise<blob URL | null>
    this.audio = new Audio()
    this.audio.preload = "auto"
    this.token = 0
  }

  // Fetch (once) and keep the clip in memory. Resolves to a blob URL, or null when
  // the server has no neural voice (204), rejects the line, or is unreachable.
  load(text) {
    if (!this.clips.has(text)) {
      const request = fetch(this.url, {
        method: "POST",
        credentials: "same-origin",
        headers: { "Content-Type": "application/json", Accept: "audio/mpeg", "X-CSRF-Token": csrfToken() },
        body: JSON.stringify({ mentor_slug: this.slug, text })
      })
        .then(async (response) => {
          if (response.status !== 200) return null
          const blob = await response.blob()
          return blob.size ? URL.createObjectURL(blob) : null
        })
        .catch(() => null)
      this.clips.set(text, request)
    }
    return this.clips.get(text)
  }

  // Resolves to "ended", "blocked" or "failed"
  async speak(text) {
    const token = ++this.token
    const src = await this.load(text)
    if (token !== this.token) return "ended" // cancelled or superseded meanwhile
    if (!src) return "failed"

    this.stop()
    return new Promise((resolve) => {
      this.finish = resolve
      const audio = this.audio
      audio.onended = () => this.settle("ended")
      audio.onerror = () => this.settle("failed")
      audio.src = src
      audio.currentTime = 0
      audio.play().catch((error) => {
        if (error.name === "NotAllowedError") this.settle("blocked")
        else if (error.name === "AbortError") this.settle("ended")
        else this.settle("failed")
      })
    })
  }

  settle(result) {
    const finish = this.finish
    this.finish = null
    finish?.(result)
  }

  stop() {
    this.token++
    this.audio.pause()
    this.settle("ended")
  }

  dispose() {
    this.stop()
    this.audio.removeAttribute("src")
    for (const clip of this.clips.values()) clip.then((url) => url && URL.revokeObjectURL(url))
    this.clips.clear()
  }
}

// Neural first, browser speech as the fallback.
export class MentorVoice {
  constructor(profile, { url, slug } = {}) {
    this.browser = new BrowserVoice(profile)
    this.neural = url && slug ? new NeuralVoice({ url, slug }) : null
  }

  get supported() {
    return Boolean(this.neural) || this.browser.supported
  }

  // Warm the clips one after another so the first lines play without delay
  prefetch(texts) {
    if (!this.neural || this.prefetched) return
    this.prefetched = true
    texts.reduce((chain, text) => chain.then(() => this.neural?.load(text)), Promise.resolve())
  }

  async speak(text) {
    if (this.neural) {
      const neural = this.neural
      const result = await neural.speak(text)
      if (result !== "failed") return result
      // No neural voice on this server (edge-tts missing/offline): browser voice from now on
      if (this.neural === neural) {
        neural.dispose()
        this.neural = null
      }
    }
    return this.browser.speak(text)
  }

  cancel() {
    this.neural?.stop()
    this.browser.cancel()
  }

  dispose() {
    this.cancel()
    this.neural?.dispose()
    this.neural = null
  }
}

function csrfToken() {
  return document.querySelector('meta[name="csrf-token"]')?.content || ""
}
